INSERT INTO reading_passages (id, exam_version_id, title, paragraphs, sources, word_count, difficulty, topic, tags, is_published, passage_slot) VALUES
('rp-pte-expansion-fill-in-blanks-rw-1', 'pte-2026-01', 'Repair cafes', '[{"label": "A", "text": "A repair cafe brings volunteers and residents together to fix household objects. Its purpose is not simply to save the price of a replacement. By explaining each step, volunteers help owners understand why an object failed and how to maintain it. Some visitors arrive expecting a free repair service, however, and feel disappointed when they must participate. Organisers therefore describe the learning element clearly before accepting bookings. They also record items that cannot be repaired. These records can reveal recurring design problems, although they cannot establish how common a fault is across all products sold. A cafe sees only the objects that people choose to bring. Manufacturers could still use this limited evidence to identify components worth investigating. The strongest argument for a cafe is consequently educational rather than statistical: a successful visit can change the way someone thinks about ownership, even when the object itself remains broken."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
('rp-pte-expansion-fill-in-blanks-r-1', 'pte-2026-01', 'Repair cafes', '[{"label": "A", "text": "A repair cafe brings volunteers and residents together to fix household objects. Its purpose is not simply to save the price of a replacement. By explaining each step, volunteers help owners understand why an object failed and how to maintain it. Some visitors arrive expecting a free repair service, however, and feel disappointed when they must participate. Organisers therefore describe the learning element clearly before accepting bookings. They also record items that cannot be repaired. These records can reveal recurring design problems, although they cannot establish how common a fault is across all products sold. A cafe sees only the objects that people choose to bring. Manufacturers could still use this limited evidence to identify components worth investigating. The strongest argument for a cafe is consequently educational rather than statistical: a successful visit can change the way someone thinks about ownership, even when the object itself remains broken."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
('rp-pte-expansion-reading-mcq-single-1', 'pte-2026-01', 'Repair cafes', '[{"label": "A", "text": "A repair cafe brings volunteers and residents together to fix household objects. Its purpose is not simply to save the price of a replacement. By explaining each step, volunteers help owners understand why an object failed and how to maintain it. Some visitors arrive expecting a free repair service, however, and feel disappointed when they must participate. Organisers therefore describe the learning element clearly before accepting bookings. They also record items that cannot be repaired. These records can reveal recurring design problems, although they cannot establish how common a fault is across all products sold. A cafe sees only the objects that people choose to bring. Manufacturers could still use this limited evidence to identify components worth investigating. The strongest argument for a cafe is consequently educational rather than statistical: a successful visit can change the way someone thinks about ownership, even when the object itself remains broken."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
('rp-pte-expansion-reading-mcq-multiple-1', 'pte-2026-01', 'Repair cafes', '[{"label": "A", "text": "A repair cafe brings volunteers and residents together to fix household objects. Its purpose is not simply to save the price of a replacement. By explaining each step, volunteers help owners understand why an object failed and how to maintain it. Some visitors arrive expecting a free repair service, however, and feel disappointed when they must participate. Organisers therefore describe the learning element clearly before accepting bookings. They also record items that cannot be repaired. These records can reveal recurring design problems, although they cannot establish how common a fault is across all products sold. A cafe sees only the objects that people choose to bring. Manufacturers could still use this limited evidence to identify components worth investigating. The strongest argument for a cafe is consequently educational rather than statistical: a successful visit can change the way someone thinks about ownership, even when the object itself remains broken."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
('rp-pte-expansion-fill-in-blanks-rw-2', 'pte-2026-01', 'Night-time bus trials', '[{"label": "A", "text": "A city transport team tested a later bus service on two routes for six weeks. Passenger numbers were modest, so an initial report recommended cancellation. Interviews subsequently showed that several shift workers had accepted evening work because the buses gave them a reliable way home. Counting journeys alone had overlooked this benefit. The team also discovered that publicity had reached regular passengers but few potential new users. A longer trial with wider advertising might therefore produce different results. Nevertheless, the interviews did not prove that demand would eventually cover operating costs. The researchers recommended comparing the service with alternatives, including a shared taxi scheme. They proposed recording who benefited, how reliably vehicles arrived and the cost per completed journey. The council postponed its final decision until this broader evidence was available."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
('rp-pte-expansion-fill-in-blanks-r-2', 'pte-2026-01', 'Night-time bus trials', '[{"label": "A", "text": "A city transport team tested a later bus service on two routes for six weeks. Passenger numbers were modest, so an initial report recommended cancellation. Interviews subsequently showed that several shift workers had accepted evening work because the buses gave them a reliable way home. Counting journeys alone had overlooked this benefit. The team also discovered that publicity had reached regular passengers but few potential new users. A longer trial with wider advertising might therefore produce different results. Nevertheless, the interviews did not prove that demand would eventually cover operating costs. The researchers recommended comparing the service with alternatives, including a shared taxi scheme. They proposed recording who benefited, how reliably vehicles arrived and the cost per completed journey. The council postponed its final decision until this broader evidence was available."}]'::jsonb, '[]'::jsonb, 0, 'medium', 'Community and research', ARRAY['PTE','Original practice'], TRUE, 'custom'),
