INSERT INTO reading_reorder_items (id, exam_version_id, exam, title, paragraphs, topic, word_count, difficulty, tags, is_published) VALUES
('ri-pte-expansion-1', 'pte-2026-01', 'PTE', 'Seed library records', '[{"label": "p3", "text": "A town library began lending packets of vegetable seeds to local gardeners."}, {"label": "p1", "text": "Before distributing the first packets, staff recorded each variety and its source."}, {"label": "p4", "text": "These records allowed returning gardeners to identify which plants had produced their new seeds."}, {"label": "p2", "text": "After the first growing season, staff used that information to prepare clearer instructions for the following year."}]'::jsonb, 'Practical investigations', 55, 'medium', ARRAY['PTE','Original practice'], TRUE),
('ri-pte-expansion-2', 'pte-2026-01', 'PTE', 'Bridge inspection', '[{"label": "p3", "text": "An engineer inspecting a footbridge noticed a narrow crack near one of its supports."}, {"label": "p1", "text": "To determine whether the crack was growing, she fixed a measuring gauge across it."}, {"label": "p4", "text": "The first month of readings from the gauge showed movement after heavy rain."}, {"label": "p2", "text": "On the basis of those readings, the council commissioned a more detailed investigation."}]'::jsonb, 'Practical investigations', 54, 'medium', ARRAY['PTE','Original practice'], TRUE),
('ri-pte-expansion-3', 'pte-2026-01', 'PTE', 'Archive relocation', '[{"label": "p3", "text": "A college decided to move its paper archive to a building with better humidity control."}, {"label": "p1", "text": "Before the move, archivists assigned a tracking number to every storage box."}, {"label": "p4", "text": "Movers scanned each number as the corresponding box left the old building."}, {"label": "p2", "text": "At the destination, a second scan confirmed that all the boxes had arrived."}]'::jsonb, 'Practical investigations', 52, 'medium', ARRAY['PTE','Original practice'], TRUE),
('ri-pte-expansion-4', 'pte-2026-01', 'PTE', 'Canteen waste', '[{"label": "p3", "text": "A school canteen wanted to understand why so much cooked food remained at lunchtime."}, {"label": "p1", "text": "For the next week, staff weighed the leftovers from each dish separately."}, {"label": "p4", "text": "Those measurements showed that one side dish accounted for most of the waste."}, {"label": "p2", "text": "The following week, the kitchen prepared a smaller quantity of that dish and measured the change."}]'::jsonb, 'Practical investigations', 55, 'medium', ARRAY['PTE','Original practice'], TRUE),
('ri-pte-expansion-5', 'pte-2026-01', 'PTE', 'Walking route signs', '[{"label": "p3", "text": "A park installed new signs along a walking route that visitors often found confusing."}, {"label": "p1", "text": "To test the signs, a ranger asked first-time visitors to follow the route without a map."}, {"label": "p4", "text": "Several of these visitors hesitated at the same junction despite the new sign."}, {"label": "p2", "text": "After observing this hesitation, the ranger moved that sign closer to the turn."}]'::jsonb, 'Practical investigations', 56, 'medium', ARRAY['PTE','Original practice'], TRUE)
